1	import { db } from "@/lib/db";
2	import { PATH_IDENTIFIER_RE, escapeHtml } from "@/lib/site-endpoint";
3	
4	// =============================================================================
5	// LIVE READ-BACK FOR PUBLISHED GENERATED SITES ("Phase 1B")
6	// =============================================================================
7	//
8	// The read half of the SiteRecord round trip (lib/site-records.ts is the write
9	// half). A page can show what has already been submitted — a class roster, a
10	// list of open listings, testimonials — with ZERO client JavaScript and ZERO
11	// CSP change, by authoring a small, fixed markup convention that this module
12	// resolves server-side, once per request, in the same route
13	// (app/api/site/[slug]/[[...path]]/route.ts) that already reads the file out
14	// of `db.projectFile`.
15	//
16	// THE CONTRACT (also documented for the builder model in lib/agent.ts)
17	// ----------------------------------------------------------------------------
18	//   <div data-kodely-records="<kind>">
19	//     <p>Nothing yet.</p>                      <-- empty-state, authored by
20	//                                                   the builder, kept as-is
21	//                                                   when there are 0 records
22	//     <template data-kodely-record-template>
23	//       <p>{{name}} — {{time}}</p>              <-- cloned once per record
24	//     </template>
25	//   </div>
26	//
27	// `{{fieldName}}` is substituted ONLY when it appears in TEXT — never inside
28	// a tag's attributes. That is not a limitation to lift later; it is the whole
29	// reason this is safe without a real DOM: a value is only ever spliced into a
30	// position that cannot become a new attribute, a new tag, or an event
31	// handler, however it is escaped. See renderTemplate() below for exactly how
32	// text is told apart from markup.
33	//
34	// WHY NOT A REAL DOM PARSER
35	// ----------------------------------------------------------------------------
36	// No new dependency is allowed, and none of jsdom/cheerio/parse5 is already a
37	// project dependency (lib/site-seo.ts's applySeo() sets the precedent: it
38	// rewrites <head> tags with plain regexes on this exact serving path). The
39	// markup this module has to understand is narrow and self-imposed — one
40	// attribute name, one child element — so a small hand-written scanner that
41	// tracks tag nesting depth is enough, and is what is built below.
42	//
43	// WHAT IS UNTRUSTED HERE
44	// ----------------------------------------------------------------------------
45	// Only the RECORD VALUES coming out of the database — the container and
46	// template markup themselves are the builder's own static HTML, already
47	// served as-is everywhere else on the site. Every record value is escaped
48	// exactly the way lib/site-endpoint.ts's escapeHtml() escapes a value before
49	// it reaches any other HTML context in this codebase; there is no second
50	// escaping routine to keep in sync.
51	
52	const CONTAINER_ATTR = "data-kodely-records";
53	const TEMPLATE_ATTR = "data-kodely-record-template";
54	
55	/** Same discipline as a record `kind` at write time (lib/site-records.ts's
56	 *  RECORD_KIND_RE) — a container whose attribute value doesn't match this is
57	 *  not a kind any record could ever have been written under, so it is left
58	 *  alone rather than queried. */
59	const KIND_RE = PATH_IDENTIFIER_RE;
60	
61	/** A field name inside `{{...}}`. Matches lib/site-endpoint.ts's FIELD_NAME_RE
62	 *  character class (not the import itself, since that one is anchored for
63	 *  whole-string validation and this needs to match inside a larger string). */
64	const PLACEHOLDER_RE = /\{\{([A-Za-z][A-Za-z0-9_-]{0,63})\}\}/g;
65	
66	/** Records rendered into any one container. Keeps a page from ever growing
67	 *  unboundedly with the site's history — a hard ceiling, not a page size a
68	 *  builder can raise from markup. */
69	const MAX_RECORDS_PER_CONTAINER = 100;
70	
71	/** HTML tags with no closing tag at all — never contribute to nesting depth,
72	 *  and can appear freely inside a container's or template's markup. */
73	const VOID_ELEMENTS = new Set([
74	  "area", "base", "br", "col", "embed", "hr", "img", "input",
75	  "link", "meta", "param", "source", "track", "wbr",
76	]);
77	
78	/** Elements whose content is not markup to recurse into — skipped to their
79	 *  own literal closing tag so a `<script>` containing the text "</div>" (or
80	 *  anything else tag-shaped) can never desynchronise the depth count. */
81	const RAW_TEXT_ELEMENTS = new Set(["script", "style", "textarea", "title"]);
82	
83	type OpenTag = { end: number; tagName: string; attrs: string; selfClosing: boolean };
84	
85	/**
86	 * Read one open (or self-closing) tag starting at `html[start] === "<"`,
87	 * respecting quoted attribute values so a `>` inside `alt="a > b"` cannot be
88	 * mistaken for the tag's own end. Returns null for anything that isn't
89	 * actually a tag start (e.g. a bare `<` in text, which real builder markup
90	 * would have written as `&lt;` but this stays defensive regardless).
91	 */
92	function readOpenTag(html: string, start: number): OpenTag | null {
93	  const nameMatch = /^<([a-zA-Z][a-zA-Z0-9-]*)/.exec(html.slice(start));
94	  if (!nameMatch) return null;
95	  const tagName = nameMatch[1].toLowerCase();
96	  let i = start + nameMatch[0].length;
97	  let quote: string | null = null;
98	  while (i < html.length) {
99	    const ch = html[i];
100	    if (quote) {
101	      if (ch === quote) quote = null;
102	      i++;
103	      continue;
104	    }
105	    if (ch === '"' || ch === "'") {
106	      quote = ch;
107	      i++;
108	      continue;
109	    }
110	    if (ch === ">") {
111	      const selfClosing = html[i - 1] === "/";
112	      return { end: i + 1, tagName, attrs: html.slice(start, i + 1), selfClosing };
113	    }
114	    i++;
115	  }
116	  return null; // unterminated tag — leave the rest of the document alone
117	}
118	
119	/**
120	 * From `from` (just past a tagName's opening `>`), find where ITS matching
121	 * closing tag ends — tracking nested same-name tags, skipping comments and
122	 * raw-text elements, and never counting a void element as needing a close.
123	 * Returns null if the document runs out before the tag is closed (malformed
124	 * or truncated markup — the caller treats that container/template as absent
125	 * rather than guessing).
126	 */
127	function findMatchingClose(
128	  html: string,
129	  tagName: string,
130	  from: number,
131	): { closeStart: number; end: number } | null {
132	  let depth = 1;
133	  let i = from;
134	  while (i < html.length) {
135	    const lt = html.indexOf("<", i);
136	    if (lt === -1) return null;
137	
138	    if (html.startsWith("<!--", lt)) {
139	      const close = html.indexOf("-->", lt + 4);
140	      i = close === -1 ? html.length : close + 3;
141	      continue;
142	    }
143	
144	    if (html[lt + 1] === "/") {
145	      const m = /^<\/([a-zA-Z][a-zA-Z0-9-]*)\s*>/.exec(html.slice(lt));
146	      if (!m) {
147	        i = lt + 2;
148	        continue;
149	      }
150	      const name = m[1].toLowerCase();
151	      const tagEnd = lt + m[0].length;
152	      if (name === tagName) {
153	        depth--;
154	        if (depth === 0) return { closeStart: lt, end: tagEnd };
155	      }
156	      i = tagEnd;
157	      continue;
158	    }
159	
160	    const tag = readOpenTag(html, lt);
161	    if (!tag) {
162	      i = lt + 1;
163	      continue;
164	    }
165	    if (RAW_TEXT_ELEMENTS.has(tag.tagName) && !tag.selfClosing) {
166	      const closeRe = new RegExp(`</${tag.tagName}\\s*>`, "i");
167	      const m = closeRe.exec(html.slice(tag.end));
168	      i = m ? tag.end + m.index + m[0].length : html.length;
169	      continue;
170	    }
171	    if (tag.tagName === tagName && !tag.selfClosing && !VOID_ELEMENTS.has(tagName)) {
172	      depth++;
173	    }
174	    i = tag.end;
175	  }
176	  return null;
177	}
178	
179	type Container = { tagName: string; kind: string; innerStart: number; innerEnd: number; outerEnd: number };
180	
181	/**
182	 * Every TOP-LEVEL `data-kodely-records="<kind>"` container in the document.
183	 * "Top-level" is deliberate: once a container is found, the scan resumes
184	 * AFTER its matching close tag rather than inside it, so nested containers
185	 * are never matched. That keeps every found range disjoint, which is what
186	 * lets renderSiteRecords() below splice them all back in a single backward
187	 * pass without one replacement invalidating another's offsets.
188	 */
189	function findContainers(html: string): Container[] {
190	  const containers: Container[] = [];
191	  let i = 0;
192	  while (i < html.length) {
193	    const lt = html.indexOf("<", i);
194	    if (lt === -1) break;
195	
196	    if (html.startsWith("<!--", lt)) {
197	      const close = html.indexOf("-->", lt + 4);
198	      i = close === -1 ? html.length : close + 3;
199	      continue;
200	    }
201	    if (html[lt + 1] === "/") {
202	      i = lt + 2;
203	      continue;
204	    }
205	
206	    const tag = readOpenTag(html, lt);
207	    if (!tag) {
208	      i = lt + 1;
209	      continue;
210	    }
211	
212	    const attrMatch =
213	      new RegExp(`${CONTAINER_ATTR}\\s*=\\s*"([^"]*)"`).exec(tag.attrs) ??
214	      new RegExp(`${CONTAINER_ATTR}\\s*=\\s*'([^']*)'`).exec(tag.attrs);
215	
216	    if (attrMatch && KIND_RE.test(attrMatch[1]) && !tag.selfClosing && !VOID_ELEMENTS.has(tag.tagName)) {
217	      const close = findMatchingClose(html, tag.tagName, tag.end);
218	      if (close) {
219	        containers.push({
220	          tagName: tag.tagName,
221	          kind: attrMatch[1],
222	          innerStart: tag.end,
223	          innerEnd: close.closeStart,
224	          outerEnd: close.end,
225	        });
226	        i = close.end; // skip the whole container: enforces non-overlap
227	        continue;
228	      }
229	    }
230	
231	    i = tag.end;
232	  }
233	  return containers;
234	}
235	
236	/** Find the immediate `<template data-kodely-record-template>` inside
237	 *  `html[from, to)` and return its own span plus its inner markup. Only the
238	 *  FIRST such template counts, per the contract's "exactly one" — a second
239	 *  one, if a builder ever wrote one, is simply left as static content
240	 *  (harmless: it renders as an inert, non-visible `<template>` in a browser
241	 *  either way, exactly as authored). */
242	function findTemplate(html: string, from: number, to: number): { start: number; end: number; inner: string } | null {
243	  let i = from;
244	  while (i < to) {
245	    const lt = html.indexOf("<", i);
246	    if (lt === -1 || lt >= to) return null;
247	
248	    if (html.startsWith("<!--", lt)) {
249	      const close = html.indexOf("-->", lt + 4);
250	      i = close === -1 ? to : close + 3;
251	      continue;
252	    }
253	    if (html[lt + 1] === "/") {
254	      i = lt + 2;
255	      continue;
256	    }
257	
258	    const tag = readOpenTag(html, lt);
259	    if (!tag) {
260	      i = lt + 1;
261	      continue;
262	    }
263	
264	    if (tag.tagName === "template" && new RegExp(`\\b${TEMPLATE_ATTR}\\b`).test(tag.attrs)) {
265	      if (tag.selfClosing) return { start: lt, end: tag.end, inner: "" };
266	      const close = findMatchingClose(html, "template", tag.end);
267	      if (close && close.end <= to) {
268	        return { start: lt, end: close.end, inner: html.slice(tag.end, close.closeStart) };
269	      }
270	      return null;
271	    }
272	
273	    i = tag.end;
274	  }
275	  return null;
276	}
277	
278	/**
279	 * Clone one template's inner markup for one record, substituting `{{field}}`
280	 * ONLY in text — never inside a tag. Splitting on `<[^>]*>` alternates
281	 * text/tag segments (`String#split` with a capturing group interleaves the
282	 * matched delimiters into the result), and only the even-indexed, non-tag
283	 * segments are ever run through the placeholder regex — a tag segment is
284	 * copied through completely untouched, `{{...}}` and all, which is what
285	 * makes attribute-position interpolation impossible rather than merely
286	 * undocumented.
287	 *
288	 * A field the record does not have renders as empty text, not as the literal
289	 * placeholder and not as an error — a record may not carry every field a
290	 * template expects (blank fields are dropped entirely at write time).
291	 * `escapeHtml` is the same function every other HTML boundary in this
292	 * codebase uses, so this shares its guarantees rather than re-deriving them.
293	 */
294	function renderTemplate(templateInner: string, fields: Record<string, string>): string {
295	  const segments = templateInner.split(/(<[^>]*>)/);
296	  return segments
297	    .map((segment, i) => {
298	      if (i % 2 === 1) return segment; // a tag itself — never touched
299	      return segment.replace(PLACEHOLDER_RE, (_m, name: string) => {
300	        const value = fields[name];
301	        return value === undefined ? "" : escapeHtml(value);
302	      });
303	    })
304	    .join("");
305	}
306	
307	/** `SiteRecord.fields` is Json; narrow it to the string map every write path
308	 *  actually produces. Defensive rather than trusting the column shape, same
309	 *  as the owner dashboard (app/projects/[id]/records/page.tsx) already is. */
310	function fieldsOf(raw: unknown): Record<string, string> {
311	  if (raw === null || typeof raw !== "object" || Array.isArray(raw)) return {};
312	  const out: Record<string, string> = {};
313	  for (const [k, v] of Object.entries(raw as Record<string, unknown>)) {
314	    if (v === null || v === undefined) continue;
315	    out[k] = String(v);
316	  }
317	  return out;
318	}
319	
320	/**
321	 * Resolve every `data-kodely-records="<kind>"` container in `html` against
322	 * the PUBLISHED, non-spam SiteRecord rows for `projectId`, and return the
323	 * document with each one filled in.
324	 *
325	 * Batches ONE query per distinct `kind` found on the page, not one per
326	 * container — a page with two containers for the same kind (should not
327	 * normally happen, but is not assumed not to) still costs one query, and a
328	 * page with none of this markup costs zero queries and returns `html`
329	 * untouched, checked via a cheap substring test before any parsing happens.
330	 */
331	export async function renderSiteRecords(html: string, projectId: string): Promise<string> {
332	  if (!html.includes(CONTAINER_ATTR)) return html;
333	
334	  const containers = findContainers(html);
335	  if (containers.length === 0) return html;
336	
337	  const kinds = [...new Set(containers.map((c) => c.kind))];
338	  const rowsByKind = new Map<string, Record<string, string>[]>();
339	  await Promise.all(
340	    kinds.map(async (kind) => {
341	      const rows = await db.siteRecord.findMany({
342	        where: { projectId, kind, status: "active", spam: false },
343	        orderBy: { createdAt: "desc" },
344	        take: MAX_RECORDS_PER_CONTAINER,
345	        select: { fields: true },
346	      });
347	      rowsByKind.set(kind, rows.map((r) => fieldsOf(r.fields)));
348	    }),
349	  );
350	
351	  // Spliced from the LAST container to the first: containers are disjoint
352	  // (findContainers never returns overlapping ranges), so replacing one never
353	  // shifts the offsets of an earlier one still to be processed.
354	  let out = html;
355	  for (let idx = containers.length - 1; idx >= 0; idx--) {
356	    const c = containers[idx];
357	    const templ = findTemplate(html, c.innerStart, c.innerEnd);
358	    if (!templ) continue; // no template child: nothing this module can render
359	
360	    const before = html.slice(c.innerStart, templ.start);
361	    const after = html.slice(templ.end, c.innerEnd);
362	    const records = rowsByKind.get(c.kind) ?? [];
363	
364	    // The <template> tag is removed from served output either way — it is a
365	    // build-time-authored template, never something a browser should be
366	    // asked to render. Zero matching records keeps the builder's own
367	    // empty-state (`before` + `after`, i.e. everything except the template);
368	    // one or more replaces the container's content with the rendered clones.
369	    const newInner =
370	      records.length === 0 ? before + after : records.map((r) => renderTemplate(templ.inner, r)).join("");
371	
372	    out = out.slice(0, c.innerStart) + newInner + out.slice(c.innerEnd);
373	  }
374	  return out;
375	}
