1	import { randomBytes, scrypt as _scrypt, timingSafeEqual, createHash } from "node:crypto";
2	import { promisify } from "node:util";
3	import { cookies } from "next/headers";
4	import { db } from "./db";
5	import { SESSION_COOKIE, AUTH_HINT_COOKIE, AUTH_HINT_VALUE } from "./auth-cookies";
6	
7	const scrypt = promisify(_scrypt) as (
8	  password: string,
9	  salt: Buffer,
10	  keylen: number,
11	) => Promise<Buffer>;
12	
13	// SESSION_COOKIE moved to ./auth-cookies, same string, same everything —
14	// proxy.ts and a browser component now need the name too and neither can
15	// import this file (it pulls in Prisma). See that file for the reasoning.
16	const SESSION_DAYS = 30;
17	
18	export async function hashPassword(password: string): Promise<string> {
19	  const salt = randomBytes(16);
20	  const key = await scrypt(password, salt, 64);
21	  return `scrypt$${salt.toString("hex")}$${key.toString("hex")}`;
22	}
23	
24	export async function verifyPassword(password: string, stored: string): Promise<boolean> {
25	  const [scheme, saltHex, keyHex] = stored.split("$");
26	  if (scheme !== "scrypt" || !saltHex || !keyHex) return false;
27	  const key = await scrypt(password, Buffer.from(saltHex, "hex"), 64);
28	  const expected = Buffer.from(keyHex, "hex");
29	  if (key.length !== expected.length) return false;
30	  return timingSafeEqual(key, expected);
31	}
32	
33	// Session tokens are stored hashed, so a database read never yields a usable cookie.
34	function hashToken(token: string) {
35	  return createHash("sha256").update(token).digest("hex");
36	}
37	
38	export async function createSession(userId: string) {
39	  const token = randomBytes(32).toString("base64url");
40	  const expiresAt = new Date(Date.now() + SESSION_DAYS * 86_400_000);
41	  await db.session.create({ data: { userId, tokenHash: hashToken(token), expiresAt } });
42	
43	  const jar = await cookies();
44	  jar.set(SESSION_COOKIE, token, {
45	    httpOnly: true,
46	    sameSite: "lax",
47	    secure: process.env.NODE_ENV === "production",
48	    path: "/",
49	    expires: expiresAt,
50	  });
51	
52	  // ── ADDED: the public "someone is signed in" hint ────────────────────────
53	  // BEHAVIOUR CHANGE, flagged: every sign-in now writes a SECOND cookie
54	  // beside the session one. It is deliberately NOT httpOnly, because the
55	  // whole point is that browser JavaScript on a statically prerendered
56	  // marketing page can read it; everything about what it may therefore
57	  // contain (nothing) is argued in lib/auth-cookies.ts.
58	  //
59	  // Same expiry as the session, so the browser drops both in the same
60	  // instant and the hint can never outlive what it is hinting at. Same path
61	  // and sameSite, so it travels exactly as far. `secure` matches too — a
62	  // hint that survived on http:// while the session did not would be the
63	  // stale-hint bug by construction.
64	  jar.set(AUTH_HINT_COOKIE, AUTH_HINT_VALUE, {
65	    httpOnly: false,
66	    sameSite: "lax",
67	    secure: process.env.NODE_ENV === "production",
68	    path: "/",
69	    expires: expiresAt,
70	  });
71	}
72	
73	export async function destroySession() {
74	  const jar = await cookies();
75	  const token = jar.get(SESSION_COOKIE)?.value;
76	  if (token) await db.session.deleteMany({ where: { tokenHash: hashToken(token) } });
77	  jar.delete(SESSION_COOKIE);
78	  // ── ADDED, and the half of the hint that actually matters ────────────────
79	  // A hint left behind here is the whole failure mode of this feature: the
80	  // marketing nav would go on offering "Portal" to someone who just signed
81	  // out, and /dashboard would bounce them to /login. Deleted in the same
82	  // function as the session so the two cannot drift — sign-out has exactly
83	  // one implementation (app/api/auth/logout/route.ts calls this), so there
84	  // is no second path that could forget.
85	  jar.delete(AUTH_HINT_COOKIE);
86	}
87	
88	export async function getCurrentUser() {
89	  const jar = await cookies();
90	  const token = jar.get(SESSION_COOKIE)?.value;
91	  if (!token) return null;
92	
93	  const session = await db.session.findUnique({
94	    where: { tokenHash: hashToken(token) },
95	    include: { user: true },
96	  });
97	  if (!session || session.expiresAt < new Date()) return null;
98	  return session.user;
99	}
100	
101	/**
102	 * The Session ROW behind the current cookie, rather than the user on it.
103	 *
104	 * Additive: nothing that existed before this function behaves differently.
105	 *
106	 * It exists because a sessions list has to be able to say "this is the one you
107	 * are using" and a revoke route has to refuse to cut its own caller off, and
108	 * both of those need the session id — which `getCurrentUser` deliberately
109	 * throws away. The alternative was to re-derive it at the call site, which
110	 * means copying SESSION_COOKIE and hashToken out of this file. A settings
111	 * screen that quietly disagrees with the real cookie name would mark the wrong
112	 * row as "this device", and there is no worse lie to tell on a security page.
113	 *
114	 * Same expiry rule as getCurrentUser: an expired row resolves to null rather
115	 * than to a session, so the two can never disagree about being signed in.
116	 */
117	export async function getCurrentSession() {
118	  const jar = await cookies();
119	  const token = jar.get(SESSION_COOKIE)?.value;
120	  if (!token) return null;
121	
122	  const session = await db.session.findUnique({ where: { tokenHash: hashToken(token) } });
123	  if (!session || session.expiresAt < new Date()) return null;
124	  return session;
125	}
126	
127	export async function requireUser() {
128	  const user = await getCurrentUser();
129	  if (!user) throw new Error("UNAUTHENTICATED");
130	  return user;
131	}
132	
133	/**
134	 * Signed in AND role === "ADMIN". Returns null otherwise — callers decide
135	 * between a 404 and a redirect rather than getting a thrown error.
136	 *
137	 * app/admin/layout.tsx already gates the admin section, and that check is the
138	 * real one. This exists so each admin PAGE and API route can assert the same
139	 * thing itself: Next's own guidance is not to treat a layout as the sole
140	 * authorization boundary, since layouts don't re-render on every navigation
141	 * within a section and route handlers don't sit under them at all. Belt and
142	 * braces on a page showing cost, margin, and customer prompts.
143	 */
144	export async function getAdminUser() {
145	  const user = await getCurrentUser();
146	  return user && user.role === "ADMIN" ? user : null;
147	}
